#### 2. Implement a Secrets Manager Pattern

Here's a recommended abstraction:

```javascript
// secrets.js
class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.provider = this.initProvider();
  }

  initProvider() {
    switch (process.env.SECRETS_PROVIDER) {
      case 'aws':
        return new AWSSecretsProvider();
      case 'gcp':
        return new GCPSecretsProvider();
      case 'azure':
        return new AzureSecretsProvider();
      case 'vault':
        return new HashiCorpVaultProvider();
      default:
        // Local dev only - warn if used in production
        if (process.env.NODE_ENV === 'production') {
          throw new Error('No secrets provider configured for production!');
        }
        return new EnvFileProvider();
    }
  }

  async getSecret(name) {
    if (this.cache.has(name)) {
      return this.cache.get(name);
    }

    const secret = await this.provider.fetch(name);
    this.cache.set(name, secret);

    // Auto-expire cache after 5 minutes
    setTimeout(() => this.cache.delete(name), 5 * 60 * 1000);

    return secret;
  }
}

module.exports = new SecretsManager();
```

