```javascript
// lib/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secret = JSON.parse(response.SecretString);
      this.cache.set(secretName, secret);

      // Auto-expire cache after 1 hour
      setTimeout(() => this.cache.delete(secretName), 3600000);

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`);
      throw new Error('Secret retrieval failed');
    }
  }

  // Redact secrets from logs
  static redact(obj, keys = ['password', 'secret', 'key', 'token']) {
    const redacted = { ...obj };
    for (const key of Object.keys(redacted)) {
      if (keys.some(k => key.toLowerCase().includes(k))) {
        redacted[key] = '[REDACTED]';
      }
    }
    return redacted;
  }
}

module.exports = new SecretsManager();
```

